import{_ as t,o as n,c as o,a2 as r}from"./chunks/framework.7R1OEGYz.js";const h=JSON.parse('{"title":"Sign in to an agent provider","description":"","frontmatter":{},"headers":[],"relativePath":"provider-login.md","filePath":"provider-login.md","lastUpdated":null}'),a={name:"provider-login.md"};function i(s,e,d,l,c,g){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sign-in-to-an-agent-provider" tabindex="-1">Sign in to an agent provider <a class="header-anchor" href="#sign-in-to-an-agent-provider" aria-label="Permalink to &quot;Sign in to an agent provider&quot;">​</a></h1><p>Complete the provider CLI&#39;s own sign-in inside an <strong>Interactive</strong> session&#39;s <strong>Terminal</strong>. AgentHub stores the resulting provider login for your account and restores it into later sessions. Signing in to the AgentHub web app is a separate login.</p><h2 id="first-login" tabindex="-1">First login <a class="header-anchor" href="#first-login" aria-label="Permalink to &quot;First login&quot;">​</a></h2><ol><li>Select the <strong>Terminal</strong> interface preference before creating your first session.</li><li>Create an Interactive session with your agent and <strong>Subscription</strong> authentication.</li><li>Follow the provider&#39;s login prompt. Use the command below if a login is needed.</li><li>Complete any browser or device authorization yourself, then check <strong>Settings → Credentials</strong> for the stored account.</li></ol><table tabindex="0"><thead><tr><th>Agent</th><th>Login in the session terminal</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>/login</code> inside Claude Code</td></tr><tr><td>Codex</td><td><code>codex login --device-auth</code></td></tr><tr><td>Cursor</td><td><code>agent login</code></td></tr><tr><td>OpenClaw</td><td><code>openclaw models auth add</code></td></tr><tr><td>OpenCode</td><td><code>opencode auth login</code>; choose the provider and complete its sign-in or enter its key</td></tr></tbody></table><p>For OpenCode Go, get the key from the OpenCode console and use it in the session&#39;s login flow. OpenCode Go and Zen use a key even when your billing is a subscription.</p><p>For <strong>API-key</strong> authentication, store the key in <strong>Settings → Credentials</strong> and choose API-key mode when creating the session. A personal AgentHub <code>oah_</code> token is for the hub API, not an agent provider key.</p><h2 id="reuse-and-manage-accounts" tabindex="-1">Reuse and manage accounts <a class="header-anchor" href="#reuse-and-manage-accounts" aria-label="Permalink to &quot;Reuse and manage accounts&quot;">​</a></h2><p>Stored provider accounts appear under <strong>Settings → Credentials</strong>, where you can remove them. Select the appropriate stored account when starting a subscription session. Complete a new terminal login when the provider requires it. Do not copy a workstation&#39;s credential files into the pod or paste login tokens into an agent chat.</p><div class="warning custom-block"><p class="custom-block-title">1.0.0-rc.1: use Terminal for first login</p><p>A new session opened in the Workspace interface can lack a terminal, and Claude&#39;s <code>/login</code> can report “isn&#39;t available in this environment”. Select the <strong>Terminal</strong> interface preference and create a new Interactive session there to complete login; an existing Workspace chat session may have no Terminal tab. This is a prerelease issue tracked in <a href="https://github.com/open-agenthub/open-agenthub/issues/114" target="_blank" rel="noreferrer">issue #114</a>.</p></div><p>This guide describes released login flows (stable <strong>0.13.1</strong>), with the prerelease workaround marked above. Background renewal changes merged after that release are not a prerequisite for these steps.</p><p>See <a href="/docs/troubleshooting#provider-login">Troubleshooting</a> if login is unavailable, and <a href="/docs/mcp">MCP clients</a> for signing an external client into AgentHub.</p>',12)])])}const u=t(a,[["render",i]]);export{h as __pageData,u as default};
